import {
	hasWHEREAndOPTIONS,
	isValidWildCard,
	invalidKey,
	getValidSectionMkeyHelper,
	getValidRoomMkeyHelper,
	getValidRoomSkeyHelper,
	getValidSectionSkeyHelper,
	isValidSort,
	setDatasetKindHelper,
} from "./QueryValidatorHelper";

export default class QueryValidator {
	public datasetID: string;
	public datasetKind: string;
	private transformationsKeyList = new Set();
	private hasTransformations = false;

	constructor(id: string) {
		this.datasetID = id;
		this.datasetKind = "";
	}

	public isValidQuery(query: unknown): boolean {
		// Check if query is of type Object, Reject with InsightError If not
		if (typeof query !== "object" || query === null) {
			return false;
		}

		const parsedQuery = JSON.parse(JSON.stringify(query));
		const topLevelKeys = Object.keys(parsedQuery);

		// Check if topLevelKeys include WHERE and OPTIONS
		if (!hasWHEREAndOPTIONS(topLevelKeys)) {
			return false;
		}
		// set kind operation here
		const optionsKeys = Object.keys(parsedQuery.OPTIONS);
		// Check if OPTIONS contains COLUMNS and if its the first element
		if (!optionsKeys.includes("COLUMNS") || optionsKeys[0] !== "COLUMNS") {
			return false;
		}
		// check the validity of each column in columns
		const columns = parsedQuery.OPTIONS[optionsKeys[0]];

		if (!Array.isArray(columns) || columns.length === 0) {
			return false;
		}

		if (this.datasetKind === "") {
			this.datasetKind = setDatasetKindHelper(columns[0]);
		}
		if (topLevelKeys.includes("TRANSFORMATIONS")) {
			if (!this.isValidTRANSFORMATIONS(parsedQuery.TRANSFORMATIONS)) {
				return false;
			}
			this.hasTransformations = true;
		}
		// Check if all keys and fields are valid inside WHERE
		if (!this.isValidOPTIONS(parsedQuery.OPTIONS) || !this.isValidWHERE(parsedQuery.WHERE)) {
			return false;
		}

		return true;
	}

	private isValidWHERE(where: any): boolean {
		const whereKeys = Object.keys(where);
		// Check if WHERE is empty
		if (whereKeys.length === 0) {
			return true;
		}

		// Check if WHERE has only 1 FILTER
		if (whereKeys.length !== 1) {
			return false;
		}

		// Check if FILTER is a LogicComparison
		if (whereKeys.includes("AND") || whereKeys.includes("OR")) {
			return this.isValidLogicComparison(where);
		}

		// Check if FILTER is a MComparison
		if (whereKeys.includes("GT") || whereKeys.includes("LT") || whereKeys.includes("EQ")) {
			return this.isValidMComparison(where);
		}

		// Check if FILTER is a SComparision
		if (whereKeys.includes("IS")) {
			return this.isValidSComparison(where);
		}

		// Check if FILTER is a Negation
		if (whereKeys.includes("NOT")) {
			return this.isValidNegation(where);
		}

		// if whereKey doesn't match with the four options, return false
		return false;
	}

	private isValidLogicComparison(filter: any): boolean {
		const logic = Object.keys(filter)[0];
		const filterList = filter[logic];

		if (!Array.isArray(filterList)) {
			return false;
		}

		if (filterList.length === 0) {
			return false;
		}

		for (const logicfilter of filterList) {
			if (Object.keys(logicfilter).length === 0) {
				return false;
			}
			if (!this.isValidWHERE(logicfilter)) {
				return false;
			}
		}
		return true;
	}

	private isValidMComparison(filter: any): boolean {
		const mcomparator = Object.keys(filter)[0];
		const mcomparison = filter[mcomparator];
		const mkey = Object.keys(mcomparison);
		const mkeyText = mkey[0];
		const mfieldValue = mcomparison[mkeyText];

		if (this.datasetKind === "sectionKind") {
			if (mkey.length !== 1 || this.getValidSectionMkey(mkeyText) === "") {
				return false;
			}
		} else {
			if (mkey.length !== 1 || this.getValidRoomMkey(mkeyText) === "") {
				return false;
			}
		}

		if (typeof mfieldValue !== "number") {
			return false;
		}
		return true;
	}

	private isValidSComparison(filter: any): boolean {
		const scomparator = Object.keys(filter)[0];
		const scomparison = filter[scomparator];
		const skey = Object.keys(scomparison);
		const skeyText = skey[0];
		const sfieldValue = scomparison[skeyText];
		if (this.datasetKind === "sectionKind") {
			if (skey.length !== 1 || this.getValidSectionSkey(skeyText) === "") {
				return false;
			}
		} else {
			if (skey.length !== 1 || this.getValidRoomSkey(skeyText) === "") {
				return false;
			}
		}

		if (typeof sfieldValue !== "string" || !isValidWildCard(sfieldValue)) {
			return false;
		}

		return true;
	}

	private isValidNegation(filter: any): boolean {
		const notFilter = filter.NOT;

		return this.isValidWHERE(notFilter);
	}

	private isValidOPTIONS(options: any): boolean {
		const optionsKeys = Object.keys(options);

		// there must be either 1 or 2 keys
		const maxOptionsKeys = 2;
		if (optionsKeys.length !== 1 && optionsKeys.length !== maxOptionsKeys) {
			return false;
		}

		// If there are two elements, make sure the second element is ORDER
		if (optionsKeys.length === maxOptionsKeys && optionsKeys[1] !== "ORDER") {
			return false;
		}
		// check the validity of each column in columns
		const columns = options[optionsKeys[0]];

		for (const col of columns) {
			if (this.hasTransformations) {
				if (!this.transformationsKeyList.has(col)) {
					return false;
				}
			} else if (this.datasetKind === "sectionKind") {
				if (this.getValidSectionMkey(col) === "" && this.getValidSectionSkey(col) === "") {
					return false;
				}
			} else {
				if (this.getValidRoomMkey(col) === "" && this.getValidRoomSkey(col) === "") {
					return false;
				}
			}
		}

		// if ORDER exists, check the validity of each key
		if (optionsKeys.length === maxOptionsKeys) {
			if (!isValidSort(options[optionsKeys[1]], columns)) {
				return false;
			}
		}

		return true;
	}

	private isValidTRANSFORMATIONS(transformations: any): boolean {
		const transformationsKeys = Object.keys(transformations);

		const maxTransformationKeys = 2;
		if (transformationsKeys.length !== maxTransformationKeys) {
			return false;
		}

		// Check if TRANSFORMATIONS contains GROUP and APPLY
		if (!transformationsKeys.includes("GROUP") || !transformationsKeys.includes("APPLY")) {
			return false;
		}
		if (!this.isValidGROUP(transformations.GROUP) || !this.isValidAPPLY(transformations.APPLY)) {
			return false;
		}

		return true;
	}

	private isValidGROUP(group: any): boolean {
		if (!Array.isArray(group) || group.length === 0) {
			return false;
		}
		for (const key of group) {
			if (this.datasetKind === "sectionKind") {
				if (this.getValidSectionMkey(key) === "" && this.getValidSectionSkey(key) === "") {
					return false;
				}
			} else {
				if (this.getValidRoomMkey(key) === "" && this.getValidRoomSkey(key) === "") {
					return false;
				}
			}
		}

		// Add all group keys to transformation key list
		for (const key of group) {
			this.transformationsKeyList.add(key);
		}
		return true;
	}

	private isValidAPPLY(apply: any): boolean {
		if (!Array.isArray(apply)) {
			return false;
		}

		const applyKeys = [];

		for (const applyRule of apply) {
			// Each item in APPLY should only have 1 key
			if (Object.keys(applyRule).length !== 1) {
				return false;
			}

			const applyKey = Object.keys(applyRule)[0];

			if (invalidKey(applyKey)) {
				return false;
			}
			const applyBody = applyRule[applyKey];

			// Each APPLY body item should only take 1 APPLYTOKEN
			if (Object.keys(applyBody).length !== 1) {
				return false;
			}

			const applyToken = Object.keys(applyBody)[0];
			const applyItem = applyBody[applyToken];

			if (!this.isValidApplyToken(applyToken, applyItem)) {
				return false;
			}

			applyKeys.push(applyKey);
		}

		// If apply key list has duplicates
		if (new Set(applyKeys).size !== applyKeys.length) {
			return false;
		}

		// Add all applyKeys to transformation key list
		for (const key of applyKeys) {
			this.transformationsKeyList.add(key);
		}
		return true;
	}

	private isValidApplyToken(token: string, key: string): boolean {
		if (token !== "MAX" && token !== "MIN" && token !== "AVG" && token !== "COUNT" && token !== "SUM") {
			return false;
		}
		// COUNT should accept all keys
		if (token === "COUNT") {
			if (this.datasetKind === "sectionKind") {
				if (this.getValidSectionMkey(key) === "" && this.getValidSectionSkey(key) === "") {
					return false;
				}
			} else {
				if (this.getValidRoomMkey(key) === "" && this.getValidRoomSkey(key) === "") {
					return false;
				}
			}
		} else if (token === "MAX" || token === "MIN" || token === "AVG" || token === "SUM") {
			if (this.datasetKind === "sectionKind") {
				if (this.getValidSectionMkey(key) === "") {
					return false;
				}
			} else {
				if (this.getValidRoomMkey(key) === "") {
					return false;
				}
			}
		}

		return true;
	}

	private getValidSectionMkey(Mkey: string): string {
		if (!this.isValidIDKey(Mkey)) {
			return "";
		}
		return getValidSectionMkeyHelper(Mkey);
	}

	private getValidRoomMkey(Mkey: string): string {
		if (!this.isValidIDKey(Mkey)) {
			return "";
		}
		return getValidRoomMkeyHelper(Mkey);
	}

	private getValidSectionSkey(Skey: string): string {
		if (!this.isValidIDKey(Skey)) {
			return "";
		}
		return getValidSectionSkeyHelper(Skey);
	}

	private getValidRoomSkey(Skey: string): string {
		if (!this.isValidIDKey(Skey)) {
			return "";
		}
		return getValidRoomSkeyHelper(Skey);
	}

	private isValidIDKey(key: string): boolean {
		const prefix = key.split("_")[0];

		if (this.datasetID === "") {
			this.datasetID = prefix;
		} else {
			if (prefix !== this.datasetID) {
				return false;
			}
		}

		return true;
	}
}

export function hasWHEREAndOPTIONS(topLevelKeys: any[]): boolean {
	// Check if topLevelKeys include WHERE and OPTIONS
	const maxTopLevelKeys = 3;
	if (topLevelKeys.length === maxTopLevelKeys - 1) {
		if (!topLevelKeys.includes("WHERE") || !topLevelKeys.includes("OPTIONS")) {
			return false;
		}
	} else if (topLevelKeys.length === maxTopLevelKeys) {
		if (
			!topLevelKeys.includes("WHERE") ||
			!topLevelKeys.includes("OPTIONS") ||
			!topLevelKeys.includes("TRANSFORMATIONS")
		) {
			return false;
		}
	} else {
		return false;
	}
	return true;
}

export function isValidWildCard(wildcard: string): boolean {
	if (wildcard.length === 0) {
		return true;
	}

	const startsWithAsterisk = wildcard[0] === "*";
	const endsWithAsterisk = wildcard[wildcard.length - 1] === "*";

	for (let i = startsWithAsterisk ? 1 : 0; i < (endsWithAsterisk ? wildcard.length - 1 : wildcard.length); i++) {
		if (wildcard[i] === "*") {
			return false;
		}
	}

	return true;
}

// Validity Functions
export function invalidKey(key: string): boolean {
	if (key === null || key.trim() === "" || key.includes("_")) {
		return true;
	}

	return false;
}

export function getValidSectionMkeyHelper(Mkey: string): string {
	const mkey = Mkey.split("_")[1];
	if (mkey === "avg" || mkey === "pass" || mkey === "fail" || mkey === "audit" || mkey === "year") {
		return mkey;
	}
	return "";
}

export function getValidRoomMkeyHelper(Mkey: string): string {
	const mkey = Mkey.split("_")[1];
	if (mkey === "lat" || mkey === "lon" || mkey === "seats") {
		return mkey;
	}
	return "";
}

export function getValidSectionSkeyHelper(Skey: string): string {
	const skey = Skey.split("_")[1];
	if (skey === "dept" || skey === "id" || skey === "instructor" || skey === "title" || skey === "uuid") {
		return skey;
	}
	return "";
}

export function getValidRoomSkeyHelper(Skey: string): string {
	const skey = Skey.split("_")[1];
	if (skey === "fullname" || skey === "shortname" || skey === "number" || skey === "name") {
		return skey;
	}
	if (skey === "address" || skey === "type" || skey === "furniture" || skey === "href") {
		return skey;
	}
	return "";
}

export function isValidSort(sort: any, columns: any): boolean {
	// Single Column
	if (typeof sort === "string") {
		// At this point, we are guaranteed all column keys are valid
		if (!columns.includes(sort)) {
			return false;
		}
	} else {
		const sortKeys = Object.keys(sort);
		const sortBodyLength = 2;
		if (sortKeys.length !== sortBodyLength || !sortKeys.includes("dir") || !sortKeys.includes("keys")) {
			return false;
		}

		if (sortKeys[0] !== "dir" && sortKeys[1] !== "keys") {
			return false;
		}

		if (sort.dir !== "UP" && sort.dir !== "DOWN") {
			return false;
		}

		if (!Array.isArray(sort.keys) || sort.keys.length === 0) {
			return false;
		}

		for (const key of sort.keys) {
			if (!columns.includes(key)) {
				return false;
			}
		}
	}

	return true;
}

export function setDatasetKindHelper(column: string): string {
	if (column.includes("fullname") || column.includes("shortname") || column.includes("number")) {
		return "roomKind";
	} else if (column.includes("address") || column.includes("lat") || column.includes("lon")) {
		return "roomKind";
	} else if (column.includes("href") || column.includes("name")) {
		return "roomKind";
	} else if (column.includes("seats") || column.includes("type") || column.includes("furniture")) {
		return "roomKind";
	} else {
		return "sectionKind";
	}
}

import { InsightDataset, InsightError, InsightResult, ResultTooLargeError } from "./IInsightFacade";
import Decimal from "decimal.js";

export default class QueryEngine {
	public datasetID: string;

	constructor(id: string) {
		this.datasetID = id;
	}

	public processQuery(query: any, id: string, datasetMap: Map<string, InsightDataset>): InsightResult[] {
		// Parse Query
		const parsedQuery = JSON.parse(JSON.stringify(query));
		// Parse Dataset
		const dataset = datasetMap.get(id);
		const parsedDataset = JSON.parse(JSON.stringify(dataset));
		let filteredResult: any = [];
		if (parsedDataset.kind === "rooms") {
			filteredResult = parsedDataset.rooms;
		} else {
			filteredResult = parsedDataset.sections;
		}
		filteredResult = this.processWHERE(parsedQuery.WHERE, filteredResult);
		if (parsedQuery.TRANSFORMATIONS) {
			filteredResult = this.processTRANSFORMATIONS(parsedQuery.TRANSFORMATIONS, filteredResult);
		}
		filteredResult = this.processOPTION(parsedQuery.OPTIONS, filteredResult);

		// AFTER RESULTS HAS BEEN PROCESSED: If the result is greater than 5000, Reject with ResultTooLarge error
		const maximumResults = 5000;
		if (filteredResult.length > maximumResults) {
			throw new ResultTooLargeError("Result is greater than 5000 entries");
		} else {
			return filteredResult;
		}
	}

	private processWHERE(queryWHERE: any, filteredResult: any): any[] {
		// If WHERE is empty, return all entries
		if (Object.keys(queryWHERE).length === 0) {
			return filteredResult;
		}

		const filter = Object.keys(queryWHERE)[0];

		// IF WHERE has FILTER, pass on current entries to the filter helper
		if (filter === "AND" || filter === "OR") {
			return this.handleLogic(queryWHERE, filteredResult);
		} else if (filter === "GT" || filter === "LT" || filter === "EQ") {
			// TODO: do i have to consider when handleMComparison throws an Error?
			return this.handleMComparison(queryWHERE, filteredResult);
		} else if (filter === "IS") {
			return this.handleSComparison(queryWHERE, filteredResult);
		} else if (filter === "NOT") {
			return this.handleNegation(queryWHERE, filteredResult);
		}
		throw new InsightError(`filter, ${filter}, is NOT valid`);
	}

	private processTRANSFORMATIONS(queryTRANSFORMATIONS: any, filteredResult: any): any[] {
		const groupKeys = queryTRANSFORMATIONS.GROUP;
		const applyRules = queryTRANSFORMATIONS.APPLY;
		const groupedData = new Map<string, any[]>();

		// Transform result into groups of data
		for (const item of filteredResult) {
			const groupName = groupKeys.map((key: string) => item[key]).join("|");
			if (!groupedData.has(groupName)) {
				groupedData.set(groupName, []);
			}
			groupedData.get(groupName)!.push(item);
		}

		const allGroups = Array.from(groupedData.values());
		const result = [];

		for (const group of allGroups) {
			let transformedGroup = group[0];

			if (applyRules.length > 0) {
				transformedGroup = this.processAPPLY(applyRules, group);
			}

			result.push(transformedGroup);
		}

		filteredResult = result;

		return filteredResult;
	}

	private processAPPLY(apply: any, group: any): any[] {
		const result = group[0];
		for (const applyRule of apply) {
			const applyKey = Object.keys(applyRule)[0];
			const applyBody = applyRule[applyKey];
			const applyToken = Object.keys(applyBody)[0];
			const applyItem = applyBody[applyToken];

			if (applyToken === "MAX") {
				result[applyKey] = this.handleMAX(applyItem, group);
			}

			if (applyToken === "MIN") {
				result[applyKey] = this.handleMIN(applyItem, group);
			}

			if (applyToken === "AVG") {
				result[applyKey] = this.handleAVG(applyItem, group);
			}

			if (applyToken === "SUM") {
				result[applyKey] = this.handleSUM(applyItem, group);
			}

			if (applyToken === "COUNT") {
				result[applyKey] = this.handleCOUNT(applyItem, group);
			}
		}

		return result;
	}

	private handleMAX(applyItem: any, group: any): number {
		let max = group[0][applyItem];
		for (const item of group) {
			if (item[applyItem] > max) {
				max = item[applyItem];
			}
		}
		return max;
	}

	private handleMIN(applyItem: any, group: any): number {
		let min = group[0][applyItem];
		for (const item of group) {
			if (item[applyItem] < min) {
				min = item[applyItem];
			}
		}
		return min;
	}

	private handleAVG(applyItem: any, group: any): number {
		let total = new Decimal(0);
		for (const item of group) {
			total = Decimal.add(total, new Decimal(item[applyItem]));
		}
		const numRows = group.length;
		const avg = total.toNumber() / numRows;
		const decimalPlace = 2;
		return Number(avg.toFixed(decimalPlace));
	}

	private handleSUM(applyItem: any, group: any): number {
		let sum = 0;
		for (const item of group) {
			sum += item[applyItem];
		}
		const decimalPlace = 2;
		return Number(sum.toFixed(decimalPlace));
	}

	private handleCOUNT(applyItem: any, group: any): number {
		const uniqueList: any[] = [];
		for (const item of group) {
			if (!uniqueList.includes(item[applyItem])) {
				uniqueList.push(item[applyItem]);
			}
		}
		return uniqueList.length;
	}

	private processOPTION(queryOPTION: any, filteredResult: any): any[] {
		const columnKeys = queryOPTION.COLUMNS;
		const result: any[] = [];

		for (const item of filteredResult) {
			const orderedItem: any = {};
			for (const key of columnKeys) {
				orderedItem[key] = item[key];
			}
			result.push(orderedItem);
		}

		filteredResult = result;

		if (queryOPTION.ORDER !== null && queryOPTION.ORDER !== undefined) {
			filteredResult = this.processORDER(queryOPTION.ORDER, filteredResult);
		}

		return filteredResult;
	}

	private processORDER(queryORDER: any, filteredResult: any): any[] {
		if (typeof queryORDER === "string") {
			filteredResult = this.handleSort(queryORDER, filteredResult);
		} else {
			filteredResult = this.handleSortDir(queryORDER, filteredResult);
		}

		return filteredResult;
	}

	private handleSort(queryORDER: any, filteredResult: any): any[] {
		filteredResult.sort(function (a: any, b: any) {
			if (a[queryORDER] > b[queryORDER]) {
				return 1;
			} else if (a[queryORDER] < b[queryORDER]) {
				return -1;
			}
		});
		return filteredResult;
	}

	private handleSortDir(queryORDER: any, filteredResult: any): any[] {
		if (queryORDER.dir === "UP") {
			filteredResult.sort(function (a: any, b: any) {
				for (const key of queryORDER.keys) {
					if (a[key] > b[key]) {
						return 1;
					} else if (a[key] < b[key]) {
						return -1;
					}
				}
				return 0;
			});
		} else {
			filteredResult.sort(function (a: any, b: any) {
				for (const key of queryORDER.keys) {
					if (a[key] > b[key]) {
						return -1;
					} else if (a[key] < b[key]) {
						return 1;
					}
				}
				return 0;
			});
		}
		return filteredResult;
	}

	private handleLogic(queryLOGIC: any, filteredResult: any): any[] {
		const logic = Object.keys(queryLOGIC)[0];
		const filterList = queryLOGIC[logic];
		let result: any[] = [];

		// Case AND
		if (logic === "AND") {
			for (const filter of filterList) {
				filteredResult = this.processWHERE(filter, filteredResult);
			}
			result = filteredResult;
		}

		// Case OR
		else {
			// create a huge list of all sections that match each filter
			let filteredOR: any[] = [];

			for (const filter of filterList) {
				filteredOR = filteredOR.concat(this.processWHERE(filter, filteredResult));
			}

			result = Array.from(new Set(filteredOR));
		}

		return result;
	}

	private handleMComparison(queryMComparator: any, filteredResult: any): any[] {
		const mcomparator = Object.keys(queryMComparator)[0];
		const mcomparison = queryMComparator[mcomparator];
		const mkey = Object.keys(mcomparison);
		const mkeyText = mkey[0];
		const mfieldValue = mcomparison[mkeyText];
		const result = [];

		for (const section of filteredResult) {
			const sectionValue = section[mkeyText];

			switch (mcomparator) {
				case "EQ": {
					if (sectionValue === mfieldValue) {
						result.push(section);
					}
					break;
				}
				case "GT": {
					if (sectionValue > mfieldValue) {
						result.push(section);
					}
					break;
				}
				case "LT": {
					if (sectionValue < mfieldValue) {
						result.push(section);
					}
					break;
				}
				default:
				// console.error(`Invalid comparator: ${mcomparator}`);
			}
		}
		return result;
	}

	private handleSComparison(querySComparator: any, filteredResult: any): any[] {
		const scomparator = Object.keys(querySComparator)[0];
		const scomparison = querySComparator[scomparator];
		const skey = Object.keys(scomparison)[0];
		const sfieldValue = scomparison[skey];
		if (sfieldValue === "*" || sfieldValue === "**") {
			return filteredResult;
		}
		return filteredResult.filter((section: any) => {
			const sectionValue = section[skey];
			if (sfieldValue.startsWith("*") && sfieldValue.endsWith("*")) {
				return sectionValue.includes(sfieldValue.slice(1, -1));
			} else if (sfieldValue.startsWith("*")) {
				return sectionValue.endsWith(sfieldValue.slice(1));
			} else if (sfieldValue.endsWith("*")) {
				return sectionValue.startsWith(sfieldValue.slice(0, -1));
			} else {
				return sectionValue === sfieldValue;
			}
		});
	}

	private handleNegation(queryNegation: any, filteredResult: any): any[] {
		const result = [];
		const negatedResult = this.processWHERE(queryNegation.NOT, filteredResult);

		for (const section of filteredResult) {
			if (!negatedResult.includes(section)) {
				result.push(section);
			}
		}
		return result;
	}
}
